from lxml import objectify
from taf.internal.scf.tree_object import TreeListObject
from taf.internal.scf.p import P
from taf.internal.scf.exceptions import ElementNotFound


class Item(TreeListObject):
    def __init__(self, tree=None):
        super(Item, self).__init__(tree)

    def __getattr__(self, item):
        if item.startswith("__"):
            return super(Item, self).__getattr__(item)
        try:
            classes = [('p', P)]
            element = self.find_element(item, self._tree)
            return self.return_scf_element(element, classes)
        except IndexError:
            raise ElementNotFound()

    class ItemIterator:
        def __init__(self, tree):
            self._tree = tree
            self._current_index = 0

        def __next__(self):
            index = self._current_index
            try:
                child = self._tree.getchildren()[index]
                self._current_index += 1
                return P(child)
            except IndexError:
                self._current_index = 0
                raise StopIteration

        def next(self):
            return self.__next__()

        def __iter__(self):
            return self

    def __iter__(self):
        return Item.ItemIterator(self._tree)

    def __getitem__(self, item):
        classes = [('p', P)]
        return self._get_children(item, self._tree, classes)

    def __len__(self):
        return len(self._tree.getchildren())

    def __getslice__(self, i, j):
        return self.__getitem__(slice(i, j))

    def create(self, ns='raml21.xsd'):
        element = objectify.ObjectifiedElement()
        element.tag = '{' + ns + '}item'
        self._tree = element
        return self
